<?php if($iiState['original']!==null&&($iiState['blocked']||$error!=='')): ?><section class="card iv-invoice-original" data-inventory-invoice-original><h3><?= e($iiText('Rechnungsdatei-Auftrag')) ?></h3><p><?= e($iiText('Die vollständigen bekannten Angaben bleiben sichtbar. Es wird keine andere Datei, Gegenstandszuordnung, Anzahl oder Datumsangabe eingesetzt. Prüfe zuerst den gespeicherten Stand.')) ?></p><pre><?= e(json_encode($iiState['original'],JSON_PRETTY_PRINT|JSON_UNESCAPED_UNICODE|JSON_INVALID_UTF8_SUBSTITUTE|JSON_THROW_ON_ERROR)) ?></pre><?php if($iiLookup!==null): ?><a class="btn btn-outline theme-secondary" href="<?= e(url($iiLookup).'#gegenstand-rechnungen') ?>"><?= e($iiText('Gespeicherten Stand dieses Rechnungsdatei-Auftrags prüfen')) ?></a><?php endif ?><a class="btn btn-outline theme-secondary" href="<?= e(url($iiNew).'#gegenstand-rechnungen') ?>"><?= e($iiText('Gegenstand und Rechnungsdateien neu prüfen')) ?></a><p><?= e($iiText('Browser dürfen ausgewählte Dateien nach einem Seitenwechsel nicht selbst wieder einsetzen. Wenn der Auftrag noch nicht gespeichert wurde, wähle dieselben ursprünglichen Dateien bewusst erneut aus. Bereits vorbereitete Dateien behalten ihre Titel und Datumsangaben, solange die private Vorbereitung verfügbar ist.')) ?></p></section><?php endif ?>
<?php if($iiState['saved']!==null): ?><section class="card iv-invoice-original" data-inventory-invoice-recorded><h3><?= e($iiText('Dieser Rechnungsdatei-Auftrag wurde bereits gespeichert.')) ?></h3><p><?= e($iiText('Du liest den vorhandenen vollständigen Dateiauftrag. Es wurde keine weitere Datei und keine Zahlung angelegt. Die ursprüngliche Dateiliste bleibt geschlossen; spätere bewusste Dokumentänderungen bleiben erhalten.')) ?></p><ul><?php foreach($iiState['saved']as$row): ?><li><strong><?= e($row['original_file']['name']) ?></strong><p><?= e($iiText('Erste gespeicherte Datei: {bytes} Byte',['bytes'=>(string)$row['original_file']['size']])) ?></p><p><?= e($iiText('Heutiger Dokumenttitel: {title}',['title'=>$row['document']['title']])) ?></p><p><?= e($iiText('Heutiges Dokumentdatum: {date}',['date'=>dateDe($row['document']['document_date'])])) ?></p><a class="btn btn-outline theme-secondary" href="<?= e(url(['document_file'=>$row['document']['id']])) ?>"><?= e($iiText('Aktuelle Datei herunterladen')) ?></a></li><?php endforeach ?></ul><a class="btn btn-solid theme-primary" href="<?= e(url($iiNew).'#gegenstand-rechnungen') ?>"><?= e($iiText('Weiteren Rechnungsdatei-Auftrag vorbereiten')) ?></a></section><?php elseif(!$iiState['blocked']&&array_key_exists('invoice_request',$_GET)): ?><p role="status" data-inventory-invoice-unconfirmed><?= e($iiText('Unter dieser ursprünglichen Kennung ist noch kein vollständiger Rechnungsdatei-Auftrag gespeichert. Prüfe den Gegenstand und die ursprünglichen Dateien vor einer bewussten Bestätigung.')) ?></p><?php endif ?>
